// `Space` is not exported; `Conn`, which is, hands one out.
class Space {
  sent: i32 = 3;

  unsent(total: i32): i32 {
    return total - this.sent;
  }
}

export class Conn {
  initial: Space;

  constructor() {
    this.initial = new Space();
  }

  space(): Space {
    return this.initial;
  }
}
